function Sidebar({open,setOpen,page,setPage,onLogout}) {
  const [expanded,setExpanded]=useState('')
  return <><div className={`backdrop ${open?'show':''}`} onClick={()=>setOpen(false)}/><aside className={`sidebar ${open?'open':''}`}>
    <div className="brand"><img src="/ayush/logo-navbar-clean.png"/><button onClick={()=>setOpen(false)}><Icon name="close"/></button></div>
    <nav>{nav.map(([id,label,icon,subs],i)=><div key={id}>
      {i===12&&<div className="nav-rule"/>}<button className={`nav-item ${page===id?'active':''}`} onClick={()=>{if(id==='logout'){onLogout?.();return} if(subs)setExpanded(expanded===id?'':id); else {setPage(id);setOpen(false)}}}>
        <Icon name={icon}/><span>{label}</span>{id==='messages'&&<b className="count">12</b>}{subs&&<i className={expanded===id?'up':''}><Icon name="chevron" size={15}/></i>}
      </button>{subs&&<div className={`submenu ${expanded===id?'open':''}`}>{subs.map(x=><button key={x} onClick={()=>{setPage(id);setOpen(false)}}>{x}</button>)}</div>}
    </div>)}</nav>
    <div className="side-art"><span>Pure traditions.<br/><b>Thoughtfully managed.</b></span></div>
  </aside></>
}

function Header({setOpen,page,setPage,onLogout}){
  const [profile,setProfile]=useState(false),[notifications,setNotifications]=useState(false)
  return <header className="topbar"><div className="top-left"><button className="icon-btn" onClick={()=>setOpen(true)}><Icon name="menu"/></button><div className="crumb"><span>Admin</span><b>/</b><strong>{page[0].toUpperCase()+page.slice(1)}</strong></div></div>
    <div className="top-actions"><label className="search"><Icon name="search" size={17}/><input placeholder="Search anything..."/></label><button className="date-chip"><Icon name="calendar" size={17}/>21 May – 28 May <Icon name="chevron" size={13}/></button>
      <div className="pop-wrap"><button className="icon-btn notification" onClick={()=>setNotifications(!notifications)}><Icon name="bell"/><b>8</b></button>{notifications&&<div className="dropdown notifications"><strong>Notifications</strong><p>6 new orders received</p><p>3 products are low in stock</p><button>Mark all as read</button></div>}</div>
      <div className="pop-wrap"><button className="profile" onClick={()=>setProfile(!profile)}><span className="avatar">A</span><span><b>Admin</b><small>Super Admin</small></span><Icon name="chevron" size={14}/></button>{profile&&<div className="dropdown"><button onClick={()=>setPage('settings')}>Admin profile</button><button onClick={()=>setPage('settings')}>Settings</button><button className="danger" onClick={onLogout}>Logout</button></div>}</div>
    </div></header>
}

function StatCard({type,label,value,trend,tone,onClick}) {const icons={revenue:'rupee',orders:'cart',customers:'users',products:'box',pending:'clipboard'};return <article className="stat-card" onClick={onClick} role={onClick?'button':undefined} tabIndex={onClick?0:undefined}><div className={`stat-icon ${tone}`}><Icon name={icons[type]} size={27}/></div><div className="stat-copy"><span>{label}</span><div><strong>{value}</strong><em className={tone==='alert'?'down':''}>↑ {trend}</em></div><small>vs last 7 days</small></div></article>}

function SalesChart(){return <div className="chart-wrap"><div className="y-labels"><span>₹2,00,000</span><span>₹1,50,000</span><span>₹1,00,000</span><span>₹50,000</span><span>₹0</span></div><svg className="sales-chart" viewBox="0 0 800 230" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#55a143" stopOpacity=".26"/><stop offset="1" stopColor="#55a143" stopOpacity="0"/></linearGradient></defs><g className="grid-lines"><path d="M0 10H800M0 60H800M0 110H800M0 160H800M0 210H800"/></g><path className="area" d="M0 168 C45 140 66 154 104 124 S170 110 205 100 S266 59 314 87 S383 133 426 130 S489 116 530 109 S581 92 616 37 S680 18 720 54 S766 89 800 79 L800 210L0 210Z"/><path className="line" d="M0 168 C45 140 66 154 104 124 S170 110 205 100 S266 59 314 87 S383 133 426 130 S489 116 530 109 S581 92 616 37 S680 18 720 54 S766 89 800 79"/><g className="dots">{[[0,168],[104,124],[205,100],[314,87],[426,130],[530,109],[616,37],[720,54],[800,79]].map((p,i)=><circle key={i} cx={p[0]} cy={p[1]} r="4"/>)}</g></svg><div className="x-labels">{['21 May','22 May','23 May','24 May','25 May','26 May','27 May','28 May'].map(x=><span key={x}>{x}</span>)}</div></div>}

function Donut({order=false}){return <div className="donut-box"><div className={`donut ${order?'order':''}`}>{order&&<span><b>1,248</b><small>Total Orders</small></span>}</div><div className="legend">{(order?[['Pending','28'],['Processing','156'],['Shipped','342'],['Delivered','679'],['Cancelled','43']]:[['Website','65%'],['Mobile App','20%'],['WhatsApp','10%'],['Others','5%']]).map((x,i)=><div key={x[0]}><i className={`c${i}`}/><span>{x[0]}</span><b>{x[1]}</b></div>)}</div></div>}

function Dashboard({toast,setPage}){
  return <><div className="welcome"><div><h1>Welcome back, Admin! <span>👋</span></h1><p>Here’s what’s happening with your store today.</p></div><select><option>Last 7 Days</option><option>Today</option><option>Last 30 Days</option><option>This Month</option></select></div>
    <section className="stats"><StatCard type="revenue" label="Total Revenue" value="₹12,45,678" trend="12.5%" tone="green" onClick={()=>setPage('analytics')}/><StatCard type="orders" label="Total Orders" value="1,248" trend="8.2%" tone="red" onClick={()=>setPage('orders')}/><StatCard type="customers" label="Total Customers" value="3,652" trend="15.3%" tone="orange" onClick={()=>setPage('customers')}/><StatCard type="products" label="Total Products" value="256" trend="5.6%" tone="green" onClick={()=>setPage('products')}/><StatCard type="pending" label="Pending Orders" value="28" trend="14.7%" tone="alert" onClick={()=>setPage('orders')}/></section>
    <div className="dashboard-grid"><section className="card sales"><div className="card-head"><div><h2><Icon name="chart"/> Sales Overview</h2><div className="chart-key"><span className="rev">Revenue</span><span className="prev">Previous period</span></div></div><select><option>This Week</option><option>This Month</option><option>This Year</option></select></div><SalesChart/></section>
      <section className="card top-products"><div className="card-head"><h2>Top Selling Products</h2><button onClick={()=>setPage('products')}>View All</button></div><div className="mini-table head"><span>Product</span><span>Sold</span><span>Revenue</span></div>{products.map(p=><div className="mini-table" key={p[0]}><span className="product-name"><img src={p[5]}/><b>{p[0]}</b></span><span>{p[4]}</span><b>{['₹2,71,000','₹2,19,000','₹1,62,000','₹1,36,000','₹93,600'][products.indexOf(p)]}</b></div>)}</section>
      <section className="card recent-orders"><div className="card-head"><h2>Recent Orders</h2><button onClick={()=>setPage('orders')}>View All Orders</button></div><div className="table-scroll"><table><thead><tr><th>Order ID</th><th>Customer</th><th>Date</th><th>Amount</th><th>Status</th><th>Payment</th><th></th></tr></thead><tbody>{orders.map(o=><tr key={o[0]}><td><b>{o[0]}</b></td><td><span className="customer"><i>{o[2]}</i>{o[1]}</span></td><td>{o[3]}</td><td><b>{o[4]}</b></td><td><span className={`badge ${o[5].toLowerCase()}`}>{o[5]}</span></td><td><span className={`pay ${o[6].toLowerCase()}`}>{o[6]}</span></td><td><button className="more" onClick={()=>toast(`Actions for ${o[0]}`)} aria-label={`Actions for ${o[0]}`}><Icon name="more"/></button></td></tr>)}</tbody></table></div></section>
      <section className="card low-stock"><div className="card-head"><h2>Low Stock Products</h2><button onClick={()=>setPage('products')}>Manage Inventory</button></div>{[['A2 Cow Ghee 1L',8,10],['Besan 1kg',12,15],['Sattu 1kg',15,20],['Maida 1kg',7,12],['Suji 1kg',9,15]].map((p,i)=><div className="stock-row" key={p[0]}><span><img src={products[i%5][5]}/><b>{p[0]}</b></span><span>{p[1]} <small>/ {p[2]}</small></span><em>Low</em></div>)}</section>
      <section className="card donut-card"><div className="card-head"><h2>Sales by Channel</h2></div><Donut/></section><section className="card donut-card"><div className="card-head"><h2>Order Status Overview</h2></div><Donut order/></section>
      <section className="card recent-customers"><div className="card-head"><h2>Recent Customers</h2><button onClick={()=>setPage('customers')}>View All</button></div>{orders.map((o,i)=><div className="customer-row" key={o[1]}><span className="customer"><i>{o[2]}</i><b>{o[1]}</b></span><span>{o[3]}</span><b>{[5,3,4,2,6][i]} orders</b></div>)}</section>
    </div></>}

function CreateOrderPage({onBack,onCreated,toast}){const submit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);onCreated?.(['#ORD'+Date.now().toString().slice(-4),data.get('customer'),'NC',new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),`₹${Number(data.get('amount')).toLocaleString('en-IN')}`,'Pending',data.get('payment')]);toast('New order created successfully')};return <div className="order-workspace-page"><div className="editor-title"><button onClick={onBack}><Icon name="arrowLeft"/></button><div><h1>Create New Order</h1><p>Orders <b>›</b> New Order</p></div></div><form className="order-create-form" onSubmit={submit}><section className="card order-form-card"><div className="editor-card-title"><span><Icon name="users"/></span><div><h2>Customer Information</h2><p>Add the customer contact and delivery details.</p></div></div><div className="order-form-grid"><label>Customer Name <em>*</em><input name="customer" required placeholder="Enter full name"/></label><label>Phone Number <em>*</em><input name="phone" required placeholder="+91 98765 43210"/></label><label>Email<input name="email" type="email" placeholder="customer@email.com"/></label><label className="wide">Delivery Address <em>*</em><textarea name="address" required rows="3" placeholder="House, street, city, state and PIN code"/></label></div></section><section className="card order-form-card"><div className="editor-card-title"><span><Icon name="cart"/></span><div><h2>Order Information</h2><p>Select product, quantity, payment and amount.</p></div></div><div className="order-form-grid"><label>Product <em>*</em><select name="product" required>{products.slice(0,10).map(p=><option key={p[0]}>{p[0]}</option>)}</select></label><label>Quantity <em>*</em><input name="quantity" type="number" min="1" defaultValue="1" required/></label><label>Amount <em>*</em><input name="amount" type="number" min="1" placeholder="0" required/></label><label>Payment <em>*</em><select name="payment"><option>COD</option><option>Paid</option></select></label><label>Payment Method<select name="method"><option>Cash on Delivery</option><option>UPI</option><option>Razorpay</option><option>Credit Card</option></select></label><label>Shipping Method<select name="shipping"><option>Standard Delivery</option><option>Express Delivery</option></select></label><label className="wide">Order Notes<textarea name="notes" rows="3" placeholder="Special instructions (optional)"/></label></div></section><div className="order-form-actions"><button type="button" onClick={onBack}>Cancel</button><button className="primary" type="submit"><Icon name="check"/> Create Order</button></div></form></div>}

function OrderDetailsPage({order,onBack,toast}){const [status,setStatus]=useState(order[5]),[payment,setPayment]=useState(order[6]);return <div className="order-workspace-page"><div className="order-detail-head"><div className="editor-title"><button onClick={onBack}><Icon name="arrowLeft"/></button><div><h1>{order[0]}</h1><p>Orders <b>›</b> Order Details</p></div></div><button className="export-btn" onClick={()=>toast(`${order[0]} invoice downloaded`)}><Icon name="download"/> Download Invoice</button></div><section className="order-detail-summary"><article className="card"><span><Icon name="users"/></span><div><small>Customer</small><b>{order[1]}</b><p>{order[1].toLowerCase().replace(' ','.')}@email.com</p></div></article><article className="card"><span><Icon name="calendar"/></span><div><small>Order Date</small><b>{order[3]}</b><p>10:30 AM</p></div></article><article className="card"><span><Icon name="rupee"/></span><div><small>Order Total</small><b>{order[4]}</b><p>Including taxes</p></div></article></section><div className="order-detail-grid"><section className="card detail-card"><h2>Order Items</h2><div className="detail-product"><img src="/ayush/product-katarr-matar.png"/><div><b>Katarr Matar</b><small>5 Bags · 600 PCS · 27 KG</small></div><strong>{order[4]}</strong></div><div className="detail-totals"><span>Subtotal <b>{order[4]}</b></span><span>Shipping <b>Free</b></span><span>Total <strong>{order[4]}</strong></span></div></section><aside className="card detail-card"><h2>Manage Order</h2><label>Order Status<select value={status} onChange={e=>setStatus(e.target.value)}><option>Pending</option><option>Processing</option><option>Shipped</option><option>Delivered</option><option>Cancelled</option></select></label><label>Payment Status<select value={payment} onChange={e=>setPayment(e.target.value)}><option>COD</option><option>Paid</option><option>Refunded</option></select></label><button className="primary" onClick={()=>toast(`${order[0]} updated: ${status}, ${payment}`)}><Icon name="check"/> Save Changes</button><button className="outline-btn" onClick={()=>toast(`Tracking link sent for ${order[0]}`)}><Icon name="truck"/> Send Tracking Link</button></aside></div></div>}

function exportOrdersToExcel(rows){const escape=value=>String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'),methods=['Cash on Delivery','UPI','Razorpay','UPI','Razorpay','Credit Card','Net Banking'];const headers=['Order ID','Customer','Email','Phone','Order Date','Order Time','Amount (INR)','Order Status','Payment Status','Payment Method'];const data=rows.map((o,i)=>[o[0],o[1],`${o[1].toLowerCase().replace(' ','.')}@email.com`,`+91 98765 4321${i}`,o[3],['10:30 AM','09:15 AM','08:45 AM','07:30 AM','06:10 AM','04:20 PM','02:50 PM'][i%7],Number(String(o[4]).replace(/[^0-9.]/g,'')),o[5],o[6],methods[i%methods.length]]);const cell=(value,type='String')=>`<Cell><Data ss:Type="${type}">${escape(value)}</Data></Cell>`;const headerRow=`<Row ss:StyleID="Header">${headers.map(h=>cell(h)).join('')}</Row>`;const body=data.map(row=>`<Row>${row.map((value,index)=>cell(value,index===6?'Number':'String')).join('')}</Row>`).join('');const xml=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet" xmlns:x="urn:schemas-microsoft-com:office:excel"><Styles><Style ss:ID="Default"><Alignment ss:Vertical="Center"/><Font ss:FontName="Calibri" ss:Size="11"/></Style><Style ss:ID="Header"><Font ss:Bold="1" ss:Color="#FFFFFF"/><Interior ss:Color="#D62828" ss:Pattern="Solid"/><Alignment ss:Horizontal="Center"/></Style></Styles><Worksheet ss:Name="Orders"><Table><Column ss:Width="90"/><Column ss:Width="120"/><Column ss:Width="165"/><Column ss:Width="110"/><Column ss:Width="95"/><Column ss:Width="75"/><Column ss:Width="90"/><Column ss:Width="95"/><Column ss:Width="95"/><Column ss:Width="120"/>${headerRow}${body}</Table><AutoFilter xmlns="urn:schemas-microsoft-com:office:excel" x:Range="R1C1:R${data.length+1}C10"/></Worksheet></Workbook>`;const blob=new Blob([xml],{type:'application/vnd.ms-excel;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`Ayush-Orders-${new Date().toISOString().slice(0,10)}.xls`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}

